impl CapabilityClient for LegalHoldClient {
    type Dependencies = PluginDependencies;
    type Error = RuntimeFailure;

    const CAPABILITY_ID: &'static str = CAPABILITY_ID;
    const DESCRIPTOR_VERSION: &'static str = DESCRIPTOR_VERSION;

    fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        Ok(Self {
            add_scope: dependencies.one::<LegalHoldAddScope>()?,
            create_hold: dependencies.one::<LegalHoldCreateHold>()?,
            get_hold: dependencies.one::<LegalHoldGetHold>()?,
            list_activity: dependencies.one::<LegalHoldListActivity>()?,
            list_holds: dependencies.one::<LegalHoldListHolds>()?,
            release_hold: dependencies.one::<LegalHoldReleaseHold>()?,
            remove_scope: dependencies.one::<LegalHoldRemoveScope>()?,
        })
    }

    fn already_connected() -> RuntimeFailure {
        RuntimeFailure::PluginFailure {
            detail: format!("Capability Port {CAPABILITY_ID} was connected more than once"),
        }
    }
}

impl CapabilityClientMany for LegalHoldClient {
    fn many_from_dependencies(
        dependencies: &PluginDependencies,
    ) -> Result<Vec<BoundCapabilityClient<Self>>, RuntimeFailure> {
        dependencies
            .bindings()
            .iter()
            .filter(|binding| binding.capability_id() == CAPABILITY_ID)
            .map(|binding| {
                Ok(BoundCapabilityClient::new(
                    binding.provider_instance(),
                    Self {
                    add_scope: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<LegalHoldAddScope>()?,
                    create_hold: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<LegalHoldCreateHold>()?,
                    get_hold: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<LegalHoldGetHold>()?,
                    list_activity: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<LegalHoldListActivity>()?,
                    list_holds: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<LegalHoldListHolds>()?,
                    release_hold: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<LegalHoldReleaseHold>()?,
                    remove_scope: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<LegalHoldRemoveScope>()?,
                    },
                ))
            })
            .collect()
    }
}

